-- Training Engine V2 Phase 3 — seed authored metadata onto public.exercises.
-- Does not insert or delete exercise rows. Does not change external_id.
-- Legacy equipment/difficulty filled only when currently blank.

UPDATE public.exercises e
SET
  primary_muscle_canonical = rec->>'primary_muscle_canonical',
  secondary_muscles_canonical = ARRAY(SELECT jsonb_array_elements_text(COALESCE(rec->'secondary_muscles_canonical', '[]'::jsonb))),
  muscle_contributions = COALESCE(rec->'muscle_contributions', '[]'::jsonb),
  primary_movement_role = rec->>'primary_movement_role',
  secondary_movement_roles = ARRAY(SELECT jsonb_array_elements_text(COALESCE(rec->'secondary_movement_roles', '[]'::jsonb))),
  substitution_group = rec->>'substitution_group',
  mechanics = rec->>'mechanics',
  loading_type = rec->>'loading_type',
  required_equipment = ARRAY(SELECT jsonb_array_elements_text(COALESCE(rec->'required_equipment', '[]'::jsonb))),
  equipment_state = rec->>'equipment_state',
  location_compatibility = ARRAY(SELECT jsonb_array_elements_text(COALESCE(rec->'location_compatibility', '[]'::jsonb))),
  is_bodyweight = (rec->>'is_bodyweight')::BOOLEAN,
  is_unilateral = (rec->>'is_unilateral')::BOOLEAN,
  execution_sides = rec->>'execution_sides',
  supports_timed_prescription = (rec->>'supports_timed_prescription')::BOOLEAN,
  prescription_mode = rec->>'prescription_mode',
  conditioning_class = NULLIF(rec->>'conditioning_class', ''),
  complexity = rec->>'complexity',
  beginner_eligible = (rec->>'beginner_eligible')::BOOLEAN,
  v2_metadata_status = rec->>'v2_metadata_status',
  equipment = CASE
    WHEN e.equipment IS NULL OR btrim(e.equipment) = '' THEN rec->>'legacy_equipment'
    ELSE e.equipment
  END,
  difficulty = COALESCE(
    e.difficulty,
    NULLIF(rec->>'difficulty', '')::public.exercise_difficulty
  ),
  exercise_type = COALESCE(
    NULLIF(rec->>'exercise_type', '')::public.exercise_type,
    e.exercise_type
  ),
  primary_muscle = CASE
    WHEN e.primary_muscle IS NULL OR btrim(e.primary_muscle) = '' THEN rec->>'primary_muscle_canonical'
    ELSE e.primary_muscle
  END
